int endcut_nframes(void) { return end_nframes; }
void endcut_frame_at(int i, int *ms, int *seq, int *start, int *nruns)
{
    if (i < 0 || i >= end_nframes) { *ms = *seq = *start = *nruns = 0; return; }
    *ms = end_frames[i].ms;
    *seq = end_frames[i].seq;
    *start = end_frames[i].start;
    *nruns = end_frames[i].nruns;
}
int endcut_run_at(int i, int *n, int *ch, int *col, int *inv)
{
    if (i < 0 || i >= (int)(sizeof end_runs/sizeof end_runs[0])) return 0;
    *n = end_runs[i].n; *ch = end_runs[i].ch; *col = end_runs[i].col; *inv = end_runs[i].inv;
    return 1;
}
